1	import * as vscode from "vscode";
2	import { readUserConfig } from "../utils/config";
3	import { resolveBackend } from "../llm/presets";
4	import { OpenAICompatibleAdapter } from "../llm/openAiCompatibleAdapter";
5	import { isOllamaReachable } from "../llm/ollamaDetection";
6	import { segment } from "../engine/segmenter";
7	import type { SegmentStore } from "../engine/segmentStore";
8	import {
9	  AuthError,
10	  MalformedResponseError,
11	  NetworkError,
12	  RateLimitError,
13	} from "../llm/adapter";
14	import { runFirstRunWizard } from "./firstRunWizard";
15	
16	export function registerStartWalkthrough(
17	  context: vscode.ExtensionContext,
18	  store: SegmentStore,
19	  output: vscode.OutputChannel,
20	): vscode.Disposable {
21	  return vscode.commands.registerCommand("codewalk.startWalkthrough", async () => {
22	    const editor = vscode.window.activeTextEditor;
23	    if (!editor) {
24	      vscode.window.showInformationMessage("Open a file first to start CodeWalk.");
25	      return;
26	    }
27	    const document = editor.document;
28	    if (document.getText().trim().length === 0) {
29	      vscode.window.showInformationMessage("This file is empty — nothing to walk through.");
30	      return;
31	    }
32	
33	    const userConfig = readUserConfig();
34	    let resolved;
35	    try {
36	      resolved = resolveBackend(userConfig);
37	    } catch (e) {
38	      showSettingsError(`CodeWalk config error: ${(e as Error).message}`);
39	      return;
40	    }
41	
42	    let finalResolved = resolved;
43	    const ollamaNotReady =
44	      resolved.backend === "ollama-local" && !(await isOllamaReachable(resolved.baseUrl));
45	    const cloudKeyMissing =
46	      resolved.backend !== "ollama-local" && resolved.requiresApiKey && !resolved.apiKey;
47	
48	    if (ollamaNotReady || cloudKeyMissing) {
49	      const wizardResult = await runFirstRunWizard();
50	      if (!wizardResult) return; // user cancelled the wizard
51	      finalResolved = wizardResult;
52	      if (
53	        finalResolved.backend === "ollama-local" &&
54	        !(await isOllamaReachable(finalResolved.baseUrl))
55	      ) {
56	        vscode.window.showErrorMessage(
57	          `CodeWalk can't reach Ollama at ${finalResolved.baseUrl}. Start Ollama and try again.`,
58	        );
59	        return;
60	      }
61	    }
62	
63	    store.clear(document.uri);
64	
65	    const adapter = new OpenAICompatibleAdapter({
66	      baseUrl: finalResolved.baseUrl,
67	      apiKey: finalResolved.apiKey,
68	      model: finalResolved.model,
69	    });
70	
71	    await vscode.window.withProgress(
72	      {
73	        location: vscode.ProgressLocation.Window,
74	        title: "CodeWalk: Analyzing…",
75	      },
76	      async () => {
77	        try {
78	          const promptsDir = context.asAbsolutePath("prompts");
79	          const segments = await segment(document, { adapter, promptsDir });
80	          store.set(document.uri, segments);
81	          output.appendLine(`[success] ${segments.length} segments for ${document.fileName}`);
82	        } catch (e) {
83	          handleError(e, output);
84	        }
85	      },
86	    );
87	  });
88	}
89	
90	function showSettingsError(message: string): void {
91	  vscode.window
92	    .showErrorMessage(message, "Open Settings")
93	    .then((action) => {
94	      if (action === "Open Settings") {
95	        vscode.commands.executeCommand("workbench.action.openSettings", "codewalk");
96	      }
97	    });
98	}
99	
100	function handleError(e: unknown, output: vscode.OutputChannel): void {
101	  if (e instanceof NetworkError) {
102	    output.appendLine(`[NetworkError] ${e.message}`);
103	    vscode.window.showErrorMessage(
104	      "CodeWalk couldn't reach the LLM. Check your connection and backend URL.",
105	    );
106	  } else if (e instanceof AuthError) {
107	    output.appendLine(`[AuthError] ${e.message}`);
108	    showSettingsError("CodeWalk's API key was rejected. Open settings to update it.");
109	  } else if (e instanceof RateLimitError) {
110	    output.appendLine(`[RateLimitError] ${e.message}${e.retryAfter ? ` retry-after: ${e.retryAfter}s` : ""}`);
111	    vscode.window.showErrorMessage("CodeWalk hit a rate limit. Try again in a moment.");
112	  } else if (e instanceof MalformedResponseError) {
113	    output.appendLine(`[MalformedResponseError] ${e.message}\nRaw: ${e.rawResponse ?? "<none>"}`);
114	    showSettingsError(
115	      "CodeWalk couldn't parse the model's response. Try a more capable model in settings.",
116	    );
117	  } else {
118	    const err = e as Error;
119	    output.appendLine(`[Unhandled] ${err.stack ?? err.message ?? String(e)}`);
120	    vscode.window.showErrorMessage(
121	      "CodeWalk encountered an unexpected error. See the Output panel.",
122	    );
123	  }
124	}
